/* Mündliche Fallbeispiele. Eigene Übungsfälle – keine Original-IHK-Aufgaben.
   Felder: title, topic, s Ausgangssituation, a Aufgabe, l strukturierte Antwort (am Antwortschema orientiert),
   k Bewertungskriterien, f typische Fehler, r Rechtsgrundlage/Lernhinweis. */
SK.faelle([
  { title: "Störender Besucher im Einkaufszentrum", topic: "Hausrecht", s: "Sie sind mit übertragenem Hausrecht im Einkaufszentrum eingesetzt. Ein Mann sitzt im Eingangsbereich, trinkt Bier und ruft vorbeigehenden Kunden Beleidigungen zu. Die Hausordnung verbietet Alkoholkonsum in den Verkehrsflächen.", a: "Schildern Sie Ihr Vorgehen und begründen Sie es rechtlich.", l: ["Lage einschätzen: eine Person, alkoholisiert, verbale Aggression, Kunden im Umfeld.", "Eigensicherung: Abstand, Kollegen informieren, nicht allein in die Enge gehen.", "Ruhig ansprechen, auf die Hausordnung hinweisen und zum Unterlassen auffordern.", "Bei Fortsetzung: Hausverbot im Namen des Betreibers aussprechen und zum Verlassen auffordern.", "Kein Platzverweis (§ 34 PolG NRW ist der Polizei vorbehalten), keine Durchsuchung, kein Einziehen des Biers – das sind keine privaten Rechte.", "Bleibt er: Hausfriedensbruch; zum Ausgang begleiten, einfache körperliche Einwirkung nur soweit erforderlich.", "Bei Widerstand oder Gefahr Polizei verständigen; Betreiber entscheidet über Strafantrag.", "Vorfall mit Zeit, Ort, Wortlaut, Zeugen dokumentieren."], k: ["Hausrecht als übertragenes privates Recht benannt", "Abstufung: Ansprache – Hausverbot – Durchsetzung", "§ 123 StGB erkannt, Antragsdelikt", "Verhältnismäßigkeit und Eigensicherung"], f: ["Sofort körperlich werden", "Von „Platzverweis“ sprechen", "Bier wegnehmen oder Ausweis verlangen und einbehalten", "Dokumentation vergessen"], r: "§§ 858–860, 903, 1004 BGB; § 123 StGB; § 185 StGB; § 34a Abs. 5 GewO" },
  { title: "Wiederkehr trotz Hausverbot", topic: "Hausrecht", s: "Gegen eine Frau besteht seit zwei Wochen ein schriftliches Hausverbot für das Kaufhaus wegen Diebstahls. Sie erkennen sie in der Parfümerieabteilung wieder.", a: "Was dürfen Sie tun, und welche Straftat steht im Raum?", l: ["Identität vergewissern – Verwechslung ausschließen, ggf. Unterlagen prüfen.", "Unauffällig Kollegen hinzuziehen.", "Die Frau ruhig und diskret ansprechen, auf das Hausverbot hinweisen.", "Zum Verlassen auffordern und zum Ausgang begleiten.", "Schon das Betreten trotz Hausverbot ist widerrechtliches Eindringen – Hausfriedensbruch.", "Keine Durchsuchung der Taschen ohne Einwilligung.", "Bei Weigerung oder erneutem Diebstahlsverdacht Polizei rufen; Personalien für den Strafantrag sichern lassen.", "Bericht an die Geschäftsleitung, die über den Strafantrag entscheidet (Frist drei Monate)."], k: ["§ 123 StGB erste Variante erkannt", "Antragserfordernis und Frist genannt", "Diskretion und Verhältnismäßigkeit", "Grenzen: keine Durchsuchung"], f: ["Bloßstellen vor Kunden", "Festnahme ohne Festnahmegrund, wenn die Identität bekannt ist", "Verwechslungsgefahr ignorieren"], r: "§ 123 StGB; § 77b StGB; § 127 Abs. 1 StPO; § 859 BGB" },
  { title: "Fotograf auf dem Werksgelände", topic: "Hausrecht", s: "Bei der Bestreifung eines umzäunten Werksgeländes treffen Sie nachts einen Mann, der Anlagen fotografiert. Er sagt, er sei Hobbyfotograf und das Tor habe offen gestanden.", a: "Wie gehen Sie vor?", l: ["Lage: unbefugte Person nachts, Motiv unklar – Diebstahlsvorbereitung oder Ausspähung möglich.", "Eigensicherung: Abstand, Handleuchte, Meldung an die Leitstelle vor der Ansprache.", "Höflich ansprechen, auf Privatgelände und Fotografierverbot hinweisen.", "Zum Verlassen auffordern und zum Tor begleiten; nach Namen fragen, Angabe ist freiwillig.", "Kamera nicht wegnehmen, Bilder nicht selbst löschen – keine Beschlagnahme.", "Bei Weigerung oder konkretem Tatverdacht Polizei verständigen und beobachten.", "Offenes Tor als Sicherheitsmangel sichern und melden.", "Vorfall mit Beschreibung der Person und Uhrzeit dokumentieren."], k: ["Befriedetes Besitztum und Hausrecht erkannt", "Keine hoheitlichen Maßnahmen", "Meldung des Mangels", "Eigensicherung im Alleindienst"], f: ["Kamera wegnehmen", "Person zum Löschen zwingen (Nötigung)", "Allein ohne Meldung vorgehen"], r: "§ 123 StGB; §§ 858, 859 BGB; § 240 StGB; DGUV Vorschrift 23 §§ 4, 8" },

  { title: "Angriff mit Flasche", topic: "Notwehr", s: "Vor dem Eingang einer Bar, in der Sie Dienst tun, zerschlägt ein abgewiesener Gast eine Flasche und kommt mit dem abgebrochenen Flaschenhals auf Sie zu.", a: "Wie dürfen Sie sich verteidigen, und wo liegen die Grenzen?", l: ["Lage: gegenwärtiger rechtswidriger Angriff mit gefährlichem Werkzeug auf Leib und Leben.", "Eigensicherung: Abstand vergrößern, Hindernis zwischen sich und den Angreifer bringen, Kollegen alarmieren.", "Laut und klar ansprechen: „Stopp! Legen Sie die Flasche weg!“", "Notwehr ist erlaubt: die Verteidigung, die erforderlich ist, um den Angriff sicher zu beenden – das mildeste wirksame Mittel.", "Zurückweichen ist nicht Pflicht, aber oft das klügste Mittel; Dritte in Sicherheit bringen.", "Endet der Angriff, endet die Notwehr – keine Vergeltung.", "Polizei und bei Verletzten Rettungsdienst rufen, Erste Hilfe leisten.", "Einsatz von Abwehrmitteln anzeigen und alles dokumentieren, Zeugen benennen."], k: ["Voraussetzungen des § 32 StGB vollständig", "Erforderlichkeit erklärt", "Ende der Notwehrlage erkannt", "Anzeige- und Dokumentationspflicht"], f: ["Notwehr als Freibrief darstellen", "Nach dem Entwaffnen weiter zuschlagen", "Erste Hilfe für den Angreifer vergessen"], r: "§ 32 StGB; § 227 BGB; § 224 StGB; § 323c StGB; § 17 BewachV" },
  { title: "Der Schubser", topic: "Notwehr", s: "Ein Besucher, dem Sie den Zutritt verweigert haben, schubst Sie mit beiden Händen vor die Brust und geht dann einen Schritt zurück. Ein Kollege ruft: „Hau ihm eine rein!“", a: "Beurteilen Sie die Lage. Dürfen Sie zuschlagen?", l: ["Lage: Der Schubser war ein Angriff, ist aber beendet – der Mann ist zurückgetreten.", "Eigensicherung: Abstand halten, Hände oben und offen, Kollegen an die Seite holen.", "Deutlich sagen: „Fassen Sie mich nicht an. Bleiben Sie zurück.“", "Kein gegenwärtiger Angriff mehr – ein Schlag wäre Vergeltung, keine Notwehr, also strafbare Körperverletzung.", "Erst bei erneutem Ansetzen zum Angriff wäre erforderliche Abwehr zulässig.", "Kollegen bremsen; ruhiges Auftreten im Team.", "Hausverbot aussprechen, bei weiterer Aggression Polizei rufen.", "Körperlichen Angriff dokumentieren; Strafantrag wegen Körperverletzung prüfen."], k: ["Gegenwärtigkeit richtig beurteilt", "Abgrenzung Notwehr – Vergeltung", "Deeskalation trotz Provokation", "Umgang mit dem Kollegen"], f: ["Jeden vorangegangenen Angriff als Rechtfertigung sehen", "Sich vom Kollegen anstacheln lassen"], r: "§ 32 StGB; § 223 StGB; § 230 StGB" },
  { title: "Faustschlag und Sturz", topic: "Notwehr", s: "Ein Angreifer schlägt auf Sie ein. Sie stoßen ihn kräftig weg; er stürzt und schlägt mit dem Kopf auf den Bordstein. Er bleibt benommen liegen.", a: "Wie ist Ihr Stoß rechtlich zu bewerten, und was müssen Sie jetzt tun?", l: ["Lage: Der Angriff war gegenwärtig und rechtswidrig; jetzt liegt eine verletzte Person am Boden.", "Eigensicherung: prüfen, ob weitere Angreifer da sind.", "Der Stoß war ein mildes, erforderliches Abwehrmittel – durch Notwehr gerechtfertigt, auch wenn die Folge schwerer ist als gewollt.", "Jetzt ist der Angriff beendet: keine weitere Gewalt.", "Sofort Erste Hilfe: Bewusstsein und Atmung prüfen, stabile Seitenlage, nicht allein lassen.", "Rettungsdienst über 112 und Polizei verständigen.", "Zeugen bitten zu bleiben.", "Sachlich dokumentieren, Vorgesetzte informieren."], k: ["Rechtfertigung trotz schwerer Folge erklärt", "Hilfspflicht gegenüber dem Angreifer erkannt", "Richtige Notrufnummern", "Zeugen und Dokumentation"], f: ["Den Verletzten liegen lassen", "Aus Angst vor Ärger nichts melden", "Den Hergang beschönigen"], r: "§ 32 StGB; § 323c StGB; § 13 StGB (Ingerenz); § 227 BGB" },

  { title: "Übergriff auf dem Parkdeck", topic: "Nothilfe", s: "Auf dem Parkdeck des bewachten Hauses sehen Sie, wie ein Mann eine Frau gegen ein Auto drückt und ihr die Handtasche entreißen will. Sie schreit um Hilfe.", a: "Was dürfen und was müssen Sie tun?", l: ["Lage: gegenwärtiger rechtswidriger Angriff auf Eigentum und körperliche Unversehrtheit einer Dritten – Raub im Versuch.", "Eigensicherung: Leitstelle informieren, auf Bewaffnung achten, Abstand beim Annähern.", "Laut ansprechen: „Sicherheitsdienst! Lassen Sie die Frau los!“ – oft bricht das den Angriff ab.", "Nothilfe ist erlaubt: erforderliche Verteidigung zugunsten der Frau.", "Der Täter ist auf frischer Tat betroffen: Festhalten nach § 127 Abs. 1 StPO möglich, wenn es ohne unvertretbares Risiko geht.", "Keine Durchsuchung, keine Vernehmung.", "Polizei rufen; Opfer betreuen, Verletzungen versorgen, ggf. Rettungsdienst.", "Täterbeschreibung, Fluchtrichtung, Zeugen und Videoaufzeichnung sichern lassen; dokumentieren."], k: ["Nothilfe korrekt eingeordnet", "Hilfspflicht (§ 323c) genannt", "Festnahmerecht mit Voraussetzungen", "Opferbetreuung"], f: ["Wegsehen, weil „nicht mein Auftrag“", "Täter verfolgen und das Opfer allein lassen", "Unverhältnismäßige Gewalt"], r: "§ 32 StGB; §§ 249, 22 StGB; § 127 Abs. 1 StPO; § 323c StGB" },
  { title: "Kollege wird angegriffen", topic: "Nothilfe", s: "Bei einer Einlasskontrolle wird Ihr Kollege von zwei Männern zu Boden gebracht und getreten.", a: "Wie handeln Sie?", l: ["Lage: gegenwärtiger Angriff zweier Personen, gemeinschaftliche gefährliche Körperverletzung, Lebensgefahr bei Tritten gegen den Kopf.", "Eigensicherung: Verstärkung und Polizei sofort anfordern, nicht kopflos hineinlaufen.", "Laute, klare Ansprache; Umstehende um Hilfe und Notruf bitten.", "Nothilfe mit den erforderlichen Mitteln – bei Tritten gegen den Kopf sind auch härtere Abwehrmittel erforderlich.", "Ziel ist das Beenden des Angriffs, nicht die Bestrafung.", "Danach: Kollegen versorgen, Rettungsdienst.", "Täter, wenn möglich, festhalten bzw. Beschreibung und Fluchtrichtung an die Polizei.", "Dokumentation, Meldung als Arbeitsunfall, Nachsorge für den Kollegen."], k: ["Lebensgefahr erkannt", "Erforderlichkeit an der Gefahr gemessen", "Unterstützung angefordert", "Arbeitsunfall und Nachsorge"], f: ["Zögern aus Angst vor Rechtsfolgen", "Allein gegen zwei ohne Alarmierung", "Arbeitsunfallmeldung vergessen"], r: "§ 32 StGB; § 224 StGB; § 127 Abs. 1 StPO; SGB VII" },

  { title: "Kind im überhitzten Auto", topic: "Notstand", s: "Auf dem Kundenparkplatz steht bei 32 Grad ein verschlossenes Auto in der Sonne. Auf dem Rücksitz sitzt ein Kleinkind, das apathisch wirkt. Der Fahrer ist trotz Ausruf nicht auffindbar.", a: "Dürfen Sie die Scheibe einschlagen? Begründen Sie.", l: ["Lage: gegenwärtige Gefahr für Leben und Gesundheit des Kindes.", "Eigensicherung: Scheibe weit weg vom Kind wählen, Hand schützen.", "Zunächst mildere Mittel: Türen prüfen, Fahrer ausrufen lassen, Zeugen hinzuziehen – ohne Zeit zu verlieren.", "Notruf 112 und 110 absetzen.", "Ist die Gefahr nicht anders abwendbar, ist das Einschlagen gerechtfertigt: Leben überwiegt das Eigentum wesentlich.", "Strafrechtlich § 34 StGB, zivilrechtlich § 904 BGB – der Eigentümer muss es dulden.", "Kind in den Schatten bringen, kühlen, betreuen bis der Rettungsdienst kommt.", "Dokumentieren: Uhrzeit, Zustand, Zeugen, Maßnahmen."], k: ["Gefahr und Interessenabwägung dargestellt", "„nicht anders abwendbar“ geprüft", "§ 34 StGB und § 904 BGB unterschieden", "Erste Hilfe und Notruf"], f: ["Aus Angst vor Sachbeschädigung nichts tun", "Notwehr statt Notstand nennen", "Kind nach dem Öffnen unbeaufsichtigt lassen"], r: "§ 34 StGB; § 904 BGB; § 323c StGB" },
  { title: "Wasserrohrbruch im Serverraum", topic: "Notstand", s: "Nachts tritt im Flur vor dem Serverraum Wasser aus der Decke. Der Raum ist mit einer Tür gesichert, für die Sie keinen Schlüssel haben. Wasser läuft bereits unter der Tür hindurch. Der Bereitschaftsdienst ist erst in 40 Minuten vor Ort.", a: "Was tun Sie, und was rechtfertigt Ihr Handeln?", l: ["Lage: erheblicher Sachschaden droht unmittelbar; Gefahr durch Wasser und Strom.", "Eigensicherung: Stromgefahr beachten, nicht ins Wasser treten, wenn elektrische Anlagen betroffen sind.", "Leitstelle, Bereitschaft und Auftraggeber informieren; Anweisungen einholen.", "Mildere Mittel: Hauptwasserhahn schließen, Wasser umleiten, Notfallschlüssel prüfen.", "Reicht das nicht, kann das Aufbrechen der Tür durch Notstand gerechtfertigt sein, wenn der drohende Schaden den an der Tür wesentlich überwiegt.", "Rechtsgrundlagen: § 34 StGB, § 904 BGB.", "Feuerwehr rufen, wenn die Lage nicht beherrschbar ist.", "Alles mit Uhrzeiten dokumentieren, Fotos nach Dienstanweisung."], k: ["Abwägung Sachwert gegen Sachwert", "Mildere Mittel zuerst", "Eigensicherung (Strom)", "Meldung und Dokumentation"], f: ["Sofort aufbrechen ohne mildere Mittel", "Stromgefahr übersehen", "Niemanden informieren"], r: "§ 34 StGB; § 904 BGB; DGUV Vorschrift 23 § 8" },

  { title: "Fahrraddieb am Ständer", topic: "Vorläufige Festnahme", s: "Vor dem bewachten Bürohaus beobachten Sie, wie ein Mann mit einem Bolzenschneider ein Fahrradschloss durchtrennt und das Rad wegschieben will.", a: "Dürfen Sie den Mann festhalten? Nennen Sie die Voraussetzungen.", l: ["Lage: Diebstahl in einem besonders schweren Fall, Täter auf frischer Tat betroffen; Werkzeug kann als Waffe dienen.", "Eigensicherung: Abstand, Bolzenschneider im Blick, Kollegen bzw. Leitstelle informieren.", "Ansprechen: „Sicherheitsdienst – bleiben Sie stehen, legen Sie das Werkzeug ab.“", "§ 127 Abs. 1 StPO: frische Tat plus Fluchtverdacht oder nicht sofort feststellbare Identität.", "Festhalten mit angemessenem Zwang ist erlaubt; keine Durchsuchung, keine Vernehmung.", "Flieht er und ist die Verfolgung zu gefährlich: beobachten, beschreiben, melden.", "Unverzüglich Polizei rufen und Person übergeben.", "Tatmittel und Fahrrad am Ort belassen; dokumentieren."], k: ["Beide Voraussetzungen des § 127 Abs. 1 StPO", "Grenzen: keine Durchsuchung", "Eigensicherung bei Werkzeug", "Übergabe an die Polizei"], f: ["Nur „frische Tat“ nennen", "Fesseln als Standard darstellen", "Jagd um jeden Preis"], r: "§ 127 Abs. 1 StPO; §§ 242, 243 StGB; § 32 StGB" },
  { title: "Der vermeintliche Täter", topic: "Vorläufige Festnahme", s: "Eine Kassiererin ruft Ihnen zu: „Der Mann im grünen Parka hat geklaut!“ Sie selbst haben nichts gesehen. Der Mann geht ruhig Richtung Ausgang.", a: "Wie verhalten Sie sich?", l: ["Lage: Tatverdacht nur vom Hörensagen; keine eigene Wahrnehmung.", "Kollegin kurz fragen: Was genau hat sie gesehen, wann, welche Ware?", "Mann höflich ansprechen und um ein klärendes Gespräch bitten – freiwillig.", "Eine Festnahme auf unsicherer Grundlage ist riskant: Bei Irrtum drohen Freiheitsberaubung, Nötigung und Schadensersatz.", "Ist die Aussage der Zeugin sicher und konkret und die Tat frisch, kommt § 127 StPO in Betracht – Risiko offen benennen.", "Keine Taschenkontrolle gegen den Willen.", "Im Zweifel Polizei rufen und beobachten; Videoaufzeichnung prüfen lassen.", "Dokumentieren, Zeugin namentlich festhalten."], k: ["Problem der fremden Wahrnehmung erkannt", "Risiko des Irrtums benannt", "Freiwilligkeit betont", "Abgewogene Lösung statt Schnellschuss"], f: ["Sofort festhalten und durchsuchen", "Mann vor Kunden beschuldigen", "Zeugin nicht befragen"], r: "§ 127 Abs. 1 StPO; §§ 239, 240 StGB; § 823 BGB" },
  { title: "Festgenommener will gehen", topic: "Vorläufige Festnahme", s: "Sie haben einen Ladendieb rechtmäßig festgehalten und ins Büro gebracht. Die Polizei verspätet sich. Nach 25 Minuten sagt er: „Ich gehe jetzt“, zeigt aber erstmals seinen Personalausweis.", a: "Dürfen Sie ihn weiter festhalten?", l: ["Lage: Identität ist jetzt feststellbar; Fluchtverdacht neu bewerten.", "Ausweis ansehen, Daten notieren – nicht einbehalten.", "Ist die Identität geklärt und besteht kein Fluchtverdacht mehr, entfällt der Festnahmegrund.", "Weiteres Festhalten wäre dann Freiheitsberaubung.", "Ware sichern, Hausverbot aussprechen, Anzeige erstatten.", "Polizei über den neuen Stand informieren.", "Ruhig erklären, was weiter geschieht.", "Zeiten und Ablauf genau dokumentieren."], k: ["Festnahmegrund muss fortbestehen", "Verhältnismäßigkeit der Dauer", "Ausweis nicht einbehalten", "Dokumentation der Zeiten"], f: ["„Bis die Polizei kommt“ als starre Regel", "Ausweis als Pfand behalten", "Tür abschließen"], r: "§ 127 Abs. 1 StPO; § 239 StGB; Art. 104 GG" },

  { title: "Parfüm in der Jackentasche", topic: "Ladendiebstahl", s: "Als Kaufhausdetektiv beobachten Sie über mehrere Minuten, wie ein Kunde ein Parfüm aus der Verpackung nimmt, in die Jackeninnentasche steckt und die Kasse passiert, ohne zu zahlen.", a: "Schildern Sie den Ablauf von der Ansprache bis zur Übergabe an die Polizei.", l: ["Lage: eigene lückenlose Beobachtung, vollendeter Diebstahl, frische Tat.", "Eigensicherung: Kollegen informieren, Ansprache hinter der Kasse, nicht im Gedränge.", "Ruhig ansprechen, als Detektiv ausweisen, ins Büro bitten.", "Ware herausverlangen; bei Weigerung Besitzkehr nach §§ 859, 860 BGB mit erforderlichen Mitteln.", "Personalien erfragen. Weist er sich aus und besteht kein Fluchtverdacht: keine Festnahme.", "Andernfalls Festhalten nach § 127 Abs. 1 StPO; keine Durchsuchung, kein erzwungenes Geständnis.", "Polizei verständigen und Person übergeben.", "Bericht, Zeugen, Ware, Videosequenz sichern; Geschäftsleitung entscheidet über Strafantrag und Hausverbot."], k: ["Lückenlose Beobachtung betont", "Besitzkehr und Festnahme unterschieden", "Verbotene Maßnahmen genannt", "Vollständige Dokumentation"], f: ["Ansprache vor der Kasse", "„Fangprämie“ selbst kassieren ohne Grundlage", "Druck zur Unterschrift"], r: "§ 242 StGB; §§ 859, 860 BGB; § 127 Abs. 1 StPO; § 248a StGB" },
  { title: "Diebin mit Kinderwagen", topic: "Ladendiebstahl", s: "Eine Mutter mit Kleinkind im Kinderwagen hat Kosmetik im Wert von 40 Euro unter der Decke des Wagens versteckt und die Kasse passiert. Bei der Ansprache beginnt das Kind zu weinen, die Frau wird laut.", a: "Wie gehen Sie vor?", l: ["Lage: Diebstahl, frische Tat; besondere Rücksicht wegen des Kindes; Zuschauer.", "Eigensicherung gering gefährdet, aber Kollegin hinzuziehen.", "Leise und sachlich sprechen, die Frau weg vom Publikum ins Büro bitten.", "Ware herausverlangen; im Kinderwagen nicht selbst wühlen – Herausgabe verlangen bzw. Polizei.", "Personalien klären; bei Ausweis und ohne Fluchtgefahr keine Festnahme.", "Das Kind bleibt bei der Mutter; Wasser, Sitzgelegenheit anbieten.", "Polizei nach Hausregel verständigen.", "Sachlich dokumentieren – ohne Wertungen über die Person."], k: ["Verhältnismäßigkeit und Menschlichkeit", "Keine Durchsuchung des Kinderwagens gegen den Willen", "Deeskalation vor Publikum", "Gleiche Regeln wie für alle"], f: ["Mutter und Kind trennen", "Moralische Vorhaltungen", "Aus Mitleid die Tat ignorieren ohne Rücksprache"], r: "§ 242 StGB; § 248a StGB; § 859 BGB; § 127 Abs. 1 StPO" },
  { title: "Flucht mit Gewalt", topic: "Ladendiebstahl", s: "Ein Mann, den Sie beim Diebstahl einer Spielekonsole beobachtet haben, stößt Sie am Ausgang zur Seite und rennt mit der Ware zum Parkplatz.", a: "Welche Straftat liegt vor, und wie reagieren Sie?", l: ["Lage: Gewalt zur Sicherung der Beute – räuberischer Diebstahl, ein Verbrechen.", "Eigensicherung: Verletzung prüfen; Verfolgung nur, wenn es ohne erhebliche Gefahr möglich ist.", "Laut ansprechen und Kollegen alarmieren.", "Notwehr bzw. Besitzkehr und Festnahme sind rechtlich möglich – aber die eigene Sicherheit geht vor Sachwerten.", "Nicht auf die Straße oder zwischen Fahrzeuge rennen.", "Polizei sofort: Beschreibung, Fluchtrichtung, Fahrzeug und Kennzeichen.", "Zeugen sichern, Video sichern lassen.", "Eigene Verletzung als Arbeitsunfall melden; Bericht fertigen."], k: ["§ 252 StGB erkannt und von § 249 abgegrenzt", "Eigensicherung vor Sachwert", "Qualität der Meldung", "Arbeitsunfall"], f: ["„Nur Diebstahl“ annehmen", "Riskante Verfolgungsjagd", "Kennzeichen nicht notieren"], r: "§ 252 StGB; § 32 StGB; § 127 Abs. 1 StPO; § 859 BGB" },

  { title: "Abgewiesener Gast", topic: "Einlasskontrolle", s: "Sie stehen an der Tür einer Diskothek. Ein sichtlich angetrunkener Gast wird von Ihnen nicht eingelassen. Er ruft: „Das ist Diskriminierung, ich zeige euch an!“ Seine Freunde stehen hinter ihm.", a: "Wie begründen Sie die Abweisung und wie führen Sie das Gespräch?", l: ["Lage: Frustration, Publikum, Gruppendruck – Eskalationsgefahr.", "Eigensicherung: seitlicher Stand, Kollege sichert, Eingang frei halten.", "Ruhig, respektvoll, Sie-Form: „Heute leider nicht – Sie wirken stark alkoholisiert. Das gilt für jeden Gast.“", "Rechtsgrundlage: Hausrecht des Betreibers; sachlicher Grund Alkoholisierung, kein Merkmal nach dem AGG.", "Keine Diskussion in der Schlange; kurzen Satz wiederholen, Alternative nennen („Gern ein anderes Mal“).", "Wortführer der Freunde einbeziehen: „Bringen Sie ihn gut nach Hause.“", "Bei Drohungen oder Übergriffen Polizei rufen.", "Bei Beschwerdeankündigung Vorfall kurz notieren."], k: ["Hausrecht und sachlicher Grund", "Abgrenzung zur Diskriminierung", "Gesichtswahrung", "Teamarbeit an der Tür"], f: ["Herablassende Sprüche", "Abweisung mit Herkunft oder Aussehen begründen", "Körperkontakt ohne Not"], r: "§ 903 BGB; §§ 1, 19 AGG; § 34a Abs. 1a GewO (Sachkundepflicht an der Diskothekentür)" },
  { title: "Messer in der Tasche", topic: "Einlasskontrolle", s: "Bei der Taschenkontrolle vor einem Konzert zeigt ein Besucher freiwillig seinen Rucksack. Sie sehen ein Einhandmesser.", a: "Was tun Sie?", l: ["Lage: gefährlicher Gegenstand; bei öffentlichen Veranstaltungen gilt ein Führverbot für Waffen.", "Eigensicherung: Abstand, Hände des Besuchers im Blick, Kollegen aufmerksam machen.", "Ruhig ansprechen: „Mit dem Messer kann ich Sie nicht einlassen.“", "Einlass verweigern – Hausrecht und Hausordnung.", "Nicht beschlagnahmen. Möglich ist nur, was die Hausordnung vorsieht, z. B. Verwahrung auf freiwilliger Basis – bei verbotenen Gegenständen nicht.", "Wegen des möglichen Verstoßes gegen das Waffengesetz Polizei nach Einsatzkonzept informieren.", "Person bis dahin nicht aus den Augen lassen, aber nicht festhalten, wenn kein Festnahmegrund vorliegt.", "Vorfall melden und dokumentieren."], k: ["§§ 42, 42a WaffG eingeordnet", "Keine Beschlagnahme", "Eigensicherung", "Abstimmung mit Polizei / Einsatzleitung"], f: ["Messer einfach wegnehmen und behalten", "Trotz Messer einlassen", "Vor anderen Gästen laut werden"], r: "§§ 42, 42a WaffG; § 903 BGB; § 34a Abs. 5 GewO" },
  { title: "Ausweis sieht gefälscht aus", topic: "Einlasskontrolle", s: "Eine Jugendliche zeigt an der Tür einer Bar einen Ausweis, der offensichtlich manipuliert ist: Das Geburtsjahr wurde überklebt.", a: "Wie reagieren Sie?", l: ["Lage: Jugendschutz; möglicher Verdacht der Urkundenfälschung.", "Eigensicherung unkritisch; ruhig bleiben, Begleiter beachten.", "Einlass verweigern – freundlich, aber bestimmt.", "Den Ausweis nicht einbehalten oder zerstören: keine Beschlagnahme.", "Auf Wunsch des Betreibers bzw. nach Dienstanweisung Polizei verständigen; die Tat ist frisch, ein Festnahmerecht käme nur bei Fluchtverdacht oder ungeklärter Identität in Betracht – bei Jugendlichen besonders zurückhaltend handeln.", "Keine Belehrungen vor Publikum.", "Betreiber informieren.", "Kurz dokumentieren."], k: ["Jugendschutz als Grund der Abweisung", "§ 267 StGB erkannt", "Kein Einbehalten des Ausweises", "Verhältnismäßigkeit gegenüber Minderjährigen"], f: ["Ausweis einziehen", "Jugendliche „zur Strafe“ festhalten", "Durchwinken, weil viel los ist"], r: "§ 4 JuSchG (Aufenthalt in Gaststätten); § 267 StGB; § 903 BGB; § 127 Abs. 1 StPO" },

  { title: "Tobender Patient in der Notaufnahme", topic: "Aggressive Personen", s: "Sie sind als Sicherheitsdienst in einer Klinik eingesetzt. Ein Mann schreit in der Notaufnahme das Pflegepersonal an, schlägt auf den Tresen und wirft einen Stuhl um, weil er seit zwei Stunden wartet.", a: "Wie gehen Sie vor?", l: ["Lage: hohe Erregung, Sachaggression, verletzliche Personen im Raum; Ursache: Angst, Schmerzen, Wartezeit.", "Eigensicherung: Abstand, Kollege hinzuziehen, Personal und Patienten aus dem Nahbereich bitten.", "Ruhig und langsam ansprechen, Namen erfragen, zuhören: „Ich sehe, dass Sie verzweifelt sind.“", "Klare Grenze: „Bitte setzen Sie sich, dann kläre ich, wie lange es noch dauert.“", "Hausrecht der Klinik: Bei fortgesetzter Störung Verweis aus dem Bereich – medizinische Notwendigkeit mit dem Personal abstimmen.", "Kein Zwang ohne Notwehr- oder Notstandslage; keine Fixierung auf eigene Faust.", "Bei Angriff auf Personen: Nothilfe, Polizei rufen.", "Dokumentieren, Schaden festhalten."], k: ["Ursachen der Aggression benannt", "Deeskalationstechniken konkret", "Abstimmung mit medizinischem Personal", "Grenzen des Zwangs"], f: ["Gegenaggression", "Patienten ohne Rücksprache hinauswerfen", "Allein handeln"], r: "§ 903 BGB; § 32 StGB; § 303 StGB; Rahmenplan Sachgebiet 6" },
  { title: "Drohung am Empfang", topic: "Aggressive Personen", s: "Ein ehemaliger Mitarbeiter erscheint am Empfang des Unternehmens und sagt: „Wenn ich den Personalchef nicht sofort spreche, passiert hier was.“ Er hat die Hand in der Jackentasche.", a: "Beschreiben Sie Ihr Verhalten.", l: ["Lage: unbestimmte Drohung, verdeckte Hand – mögliche Bewaffnung; Hausrecht.", "Eigensicherung: Abstand, Tresen als Barriere, stillen Alarm bzw. Kollegen informieren.", "Ruhig bleiben, ernst nehmen, nicht provozieren: „Ich höre Ihnen zu. Worum geht es?“", "Zeit gewinnen, keine falschen Versprechen; ihn nicht ins Haus lassen.", "Personalchef und Mitarbeiter warnen lassen, Zugang sperren.", "Keine eigene Durchsuchung; bei erkennbarer Waffe Rückzug und Schutz anderer.", "Polizei verständigen – je nach Inhalt der Drohung kommt eine Bedrohung nach § 241 StGB in Betracht.", "Wortlaut, Zeit, Beschreibung dokumentieren."], k: ["Gefahreneinschätzung (Hand in der Tasche)", "Zeit gewinnen und alarmieren", "Schutz Dritter", "§ 241 StGB als mögliche Straftat genannt"], f: ["Drohung abtun", "Mann anfassen oder Tasche abtasten", "Ihn zum Personalchef durchlassen"], r: "§ 241 StGB; § 123 StGB; § 32 StGB; § 903 BGB" },
  { title: "Pöbelnde Gruppe im Bahnhof", topic: "Aggressive Personen", s: "In der Ladenpassage eines Bahnhofs belästigt eine Gruppe von fünf jungen Männern Reisende und tritt gegen einen Mülleimer. Sie sind zu zweit auf Streife.", a: "Wie handeln Sie?", l: ["Lage: Gruppe in Überzahl, Imponierverhalten, Publikum; Hausrechtsbereich mit öffentlichem Verkehr.", "Eigensicherung: Meldung an Leitstelle vor der Ansprache, Verstärkung anfordern, Abstand, Rückzugsweg.", "Wortführer erkennen und respektvoll einzeln ansprechen; Kollege sichert.", "Kurze, klare Bitte: Verhalten einstellen, sonst Verweis aus der Passage.", "Hausverbot im Namen des Betreibers bei Fortsetzung.", "Kein Platzverweis, keine Personalienfeststellung mit Zwang.", "Bei Sachbeschädigung oder Bedrohung Polizei rufen; nicht in eine Schlägerei ziehen lassen.", "Schaden und Verlauf dokumentieren."], k: ["Gruppendynamik und Wortführer", "Eigensicherung bei Unterzahl", "Hausrecht statt Polizeibefugnis", "Rechtzeitige Verständigung der Polizei"], f: ["Die ganze Gruppe gleichzeitig anherrschen", "Auf Provokationen einsteigen", "Zu zweit körperlich durchsetzen wollen"], r: "§ 903 BGB; § 123 StGB; § 303 StGB; § 34a Abs. 1a Nr. 1 GewO" },

  { title: "Gedränge vor der Bühne", topic: "Veranstaltungen", s: "Bei einem Open-Air-Konzert beobachten Sie von Ihrer Position am Wellenbrecher, dass die Menge vor der Bühne immer dichter wird. Einzelne Personen werden über die Absperrung gehoben, einige rufen um Hilfe.", a: "Was tun Sie?", l: ["Lage: gefährliche Personendichte, Verletzungs- und Panikgefahr.", "Eigensicherung: Standfestigkeit, nicht in die Menge ziehen lassen.", "Sofort Meldung an die Einsatzleitung über Funk: Ort, Lage, Dringlichkeit.", "Hilfesuchende über die Absperrung in den Graben holen und zum Sanitätsdienst leiten.", "Entscheidungen über Unterbrechung oder Durchsagen trifft die Einsatzleitung bzw. der Veranstalter – darauf drängen.", "Ruhig auf die vorderen Reihen einwirken: „Einen Schritt zurück“ – mit Handzeichen.", "Rettungswege und Graben frei halten; Sanitätsdienst und ggf. Rettungsdienst einbinden.", "Nach dem Einsatz Meldung und Dokumentation."], k: ["Gefahr früh erkannt und gemeldet", "Meldeweg und Zuständigkeit", "Rettung über den Graben", "Ruhige Kommunikation"], f: ["Abwarten", "Eigenmächtig die Musik stoppen wollen statt zu melden", "Hektische Rufe, die Panik auslösen"], r: "Sicherheitskonzept der Veranstaltung; Rahmenplan Sachgebiet 6; § 323c StGB" },
  { title: "Versperrter Notausgang", topic: "Veranstaltungen", s: "Bei einer Firmenfeier in einer Halle stellen Sie fest, dass der Caterer Getränkekisten vor einem Notausgang gestapelt hat. Er sagt: „Nur für heute Abend, sonst haben wir keinen Platz.“", a: "Wie reagieren Sie?", l: ["Lage: verstellter Rettungsweg – akute Gefahr bei Brand oder Panik.", "Eigensicherung unkritisch.", "Freundlich, aber unmissverständlich: Der Notausgang muss sofort frei sein.", "Begründen: Rettungswege sind lebenswichtig; das ist nicht verhandelbar.", "Beim Umräumen helfen oder Alternativfläche vorschlagen.", "Bei Weigerung Veranstaltungsleitung bzw. Auftraggeber einschalten; notfalls selbst frei räumen.", "Keine Weisung befolgen, die dem Sicherungsauftrag entgegensteht.", "Mangel und Beseitigung dokumentieren; Kontrolle wiederholen."], k: ["Gefahr klar benannt", "Durchsetzung ohne Eskalation", "Eskalationsweg über die Leitung", "Nachkontrolle"], f: ["Dem Caterer nachgeben", "Nur notieren und nichts tun", "Unnötig schroff werden"], r: "DGUV Vorschrift 23 § 4 Abs. 3, § 8; Brandschutzordnung des Objekts; Bauordnungsrecht NRW zu Rettungswegen (hier nicht im Wortlaut geprüft)" },
  { title: "Bewusstloser Besucher im Festzelt", topic: "Veranstaltungen", s: "Im vollen Festzelt bricht ein Besucher zusammen. Umstehende filmen mit dem Handy, andere drängen heran.", a: "Wie handeln Sie?", l: ["Lage: medizinischer Notfall in einer Menschenmenge.", "Eigensicherung: Platz schaffen, Kollegen rufen.", "Sanitätsdienst bzw. Notruf 112 alarmieren: wo, was, wie viele.", "Erste Hilfe: Ansprechen, Atmung prüfen, stabile Seitenlage oder Wiederbelebung.", "Umstehende freundlich zurückbitten, einen Ring bilden; Einweiser für die Sanitäter abstellen.", "Filmende auffordern aufzuhören – Persönlichkeitsrecht; Geräte nicht wegnehmen.", "Zugang für Rettungskräfte frei halten.", "Angehörige betreuen, Vorfall dokumentieren."], k: ["Erste Hilfe und Notruf", "Raum schaffen, Einweisung", "Umgang mit Schaulustigen ohne Zwang", "Persönlichkeitsschutz"], f: ["Handys wegnehmen", "Nur absperren, keine Erste Hilfe", "Unklare Meldung an die Rettung"], r: "§ 323c StGB; § 201a StGB; DGUV Vorschrift 1 (Erste Hilfe)" },

  { title: "Auskunft über einen Mitarbeiter", topic: "Datenschutz", s: "Am Empfang erscheint ein Mann, zeigt eine Visitenkarte als „Inkassobeauftragter“ und fragt, ob Herr M. hier arbeitet und wann er Feierabend hat.", a: "Was antworten Sie?", l: ["Lage: Auskunftsersuchen eines Privaten über personenbezogene Daten eines Beschäftigten.", "Eigensicherung unkritisch.", "Höflich bleiben: „Dazu darf ich keine Auskunft geben.“", "Weder bestätigen noch verneinen, dass Herr M. hier arbeitet.", "Keine Rechtsgrundlage für die Übermittlung; eine Visitenkarte ist keine Legitimation.", "Anbieten, eine Nachricht an die Personalabteilung weiterzugeben.", "Bei Zudringlichkeit auf das Hausrecht verweisen.", "Vorfall der zuständigen Stelle melden und notieren."], k: ["Personenbezogene Daten erkannt", "Keine Rechtsgrundlage", "Weder bestätigen noch verneinen", "Verschwiegenheit nach BewachV"], f: ["„Ja, der hat bis 17 Uhr“", "Sich von forschem Auftreten beeindrucken lassen", "Private Handynummer herausgeben"], r: "Art. 5, 6 DS-GVO; § 17 Abs. 3 BewachV" },
  { title: "Das offene Wachbuch", topic: "Datenschutz", s: "Bei der Schichtübernahme liegt das Wachbuch aufgeschlagen auf dem Empfangstresen. Darin stehen Namen von Besuchern, Kennzeichen und ein Vermerk über einen Diebstahlsverdacht gegen eine Mitarbeiterin. Zwei Lieferanten stehen am Tresen.", a: "Was ist hier falsch, und was tun Sie?", l: ["Lage: Unbefugte können sensible personenbezogene Daten lesen.", "Wachbuch sofort schließen und außer Sichtweite legen.", "Datenschutzproblem benennen: Vertraulichkeit und Zweckbindung verletzt.", "Der Verdachtsvermerk ist besonders heikel – Rufschädigung möglich.", "Kollegen der Vorschicht sachlich ansprechen.", "Vorgesetzten informieren; prüfen lassen, ob eine meldepflichtige Datenpanne vorliegt.", "Künftig: Wachbuch verschlossen bzw. außerhalb des Besucherbereichs führen.", "Vorfall dokumentieren – ohne die Daten zu wiederholen."], k: ["Verstoß gegen Vertraulichkeit erkannt", "Sofortmaßnahme", "Meldeweg (Art. 33 DS-GVO über den Verantwortlichen)", "Vorbeugung"], f: ["„Ist doch nur ein Buch“", "Kollegen vor Lieferanten zurechtweisen", "Keine Meldung"], r: "Art. 5 Abs. 1 Buchst. f, Art. 32, 33 DS-GVO; § 17 BewachV" },

  { title: "Kamera im Pausenraum", topic: "Videoüberwachung", s: "Der Filialleiter bittet Sie, eine kleine Kamera im Pausenraum der Mitarbeiter zu verstecken, weil dort Geld aus Spinden verschwindet.", a: "Wie reagieren Sie?", l: ["Lage: heimliche Überwachung von Beschäftigten in einem Rückzugsraum.", "Ruhig erklären, dass Sie das so nicht umsetzen können.", "Pausen- und Umkleideräume gehören zum besonders geschützten Bereich; verdeckte Überwachung ist dort grundsätzlich unzulässig und kann strafbar sein.", "Verdeckte Maßnahmen sind allenfalls unter engen Voraussetzungen und nur nach rechtlicher Prüfung durch den Verantwortlichen denkbar – nicht auf Zuruf.", "Alternativen vorschlagen: bessere Spindschlösser, Hinweise an die Mitarbeiter, Anzeige bei der Polizei.", "An Datenschutzbeauftragten, Geschäftsleitung und Betriebsrat verweisen.", "Eigenen Vorgesetzten informieren.", "Anfrage dokumentieren."], k: ["Unzulässigkeit erkannt und begründet", "Weisung des Kunden nicht blind befolgt", "Alternativen", "Zuständige Stellen genannt"], f: ["Kamera einbauen, „weil der Kunde es will“", "Pauschal sagen, Video sei immer verboten", "Niemanden informieren"], r: "Art. 6 DS-GVO; § 26 BDSG; § 201a StGB; DGUV Vorschrift 23 § 4 Abs. 3" },
  { title: "Kunde verlangt Videobilder", topic: "Videoüberwachung", s: "Ein Kunde kommt aufgebracht zum Sicherheitsdienst im Parkhaus: Sein Auto wurde zerkratzt. Er verlangt, sofort die Videoaufzeichnung zu sehen und sie auf sein Handy zu bekommen.", a: "Wie gehen Sie damit um?", l: ["Lage: verständlicher Ärger; auf den Aufnahmen sind auch Dritte zu sehen.", "Zuhören, Verständnis zeigen, Daten zum Vorfall aufnehmen: Stellplatz, Zeitraum.", "Erklären: Aufnahmen dürfen nicht an Privatpersonen herausgegeben oder gezeigt werden.", "Empfehlen, Anzeige bei der Polizei zu erstatten; die Polizei kann die Aufnahmen anfordern.", "Zusichern, dass die Sicherung der Aufnahmen für den Zeitraum sofort beim Verantwortlichen veranlasst wird, damit sie nicht überschrieben werden.", "Keine eigenen Kopien, kein Abfilmen vom Monitor.", "Betreiber informieren.", "Vorgang dokumentieren."], k: ["Zweckbindung und Rechte Dritter", "Sicherung statt Herausgabe", "Weg über die Polizei", "Kundenorientierte Kommunikation"], f: ["Aufnahmen zeigen oder weitergeben", "Kunden abwimmeln, ohne die Sicherung zu veranlassen", "Selbst „ermitteln“ und Verdächtige nennen"], r: "§ 4 BDSG; Art. 5, 6 DS-GVO; § 303 StGB" },

  { title: "Brandgeruch im Technikraum", topic: "Feuer und Alarm", s: "Auf dem nächtlichen Kontrollgang riechen Sie vor dem Technikraum Rauch. Die Tür ist warm. Die Brandmeldeanlage hat noch nicht ausgelöst.", a: "Was tun Sie – in welcher Reihenfolge?", l: ["Lage: wahrscheinlicher Brand hinter geschlossener Tür; Gefahr der Durchzündung beim Öffnen.", "Eigensicherung: Tür nicht öffnen, Abstand, Fluchtweg sichern.", "Brand melden: Handfeuermelder betätigen bzw. Notruf 112 – wo, was, wie viele Personen im Gebäude.", "Personen im Gebäude warnen und Räumung nach Alarmplan einleiten.", "Türen im Umfeld schließen, keine Aufzüge.", "Kein Löschversuch hinter warmer Tür.", "Feuerwehr an der Zufahrt empfangen, Schlüssel und Informationen übergeben.", "Auftraggeber und Vorgesetzte verständigen, dokumentieren."], k: ["Warme Tür nicht öffnen", "Melden vor Löschen", "Menschenrettung vor Sachschutz", "Einweisung der Feuerwehr"], f: ["Tür aufreißen", "Erst nachsehen, dann melden", "Alleiniger Löschversuch"], r: "Brandschutzordnung; Alarmplan; DGUV Vorschrift 23 § 4; § 323c StGB" },
  { title: "Einbruchalarm um drei Uhr", topic: "Feuer und Alarm", s: "Als Interventionskraft werden Sie von der Leitstelle zu einem Autohaus geschickt: Einbruchalarm, Glasbruchmelder Ausstellungsraum. Bei Ankunft sehen Sie eine eingeschlagene Scheibe und einen Lichtschein im Gebäude.", a: "Wie verhalten Sie sich?", l: ["Lage: echter Einbruch, Täter vermutlich noch im Objekt.", "Eigensicherung: nicht hineingehen, Fahrzeug so abstellen, dass Rückzug möglich ist, Abstand.", "Sofort Rückmeldung an die Leitstelle; Polizei anfordern lassen.", "Aus sicherer Position beobachten: Personen, Fahrzeuge, Kennzeichen, Fluchtrichtung.", "Keine Festnahmeversuche allein gegen unbekannte Zahl von Tätern.", "Polizei einweisen, Schlüssel und Objektkenntnis bereitstellen.", "Nach Freigabe: Objekt sichern, Notverglasung über den Auftraggeber veranlassen.", "Einsatzbericht mit Zeiten und Feststellungen."], k: ["Kein Betreten bei Einbruchspuren", "Meldung und Beobachtung", "Zusammenarbeit mit der Polizei", "Nachsicherung"], f: ["Allein hineingehen", "Tatort betreten und Spuren zerstören", "Leitstelle nicht informieren"], r: "Alarmplan; DGUV Vorschrift 23 §§ 4, 7; § 127 Abs. 1 StPO; § 243 StGB" },
  { title: "Fehlalarm oder nicht?", topic: "Feuer und Alarm", s: "Die Brandmelderzentrale zeigt Alarm für die Küche der Kantine. Ein Koch ruft an: „Alles gut, nur angebranntes Essen, schalten Sie das bitte ab, die Feuerwehr soll nicht kommen.“", a: "Wie handeln Sie?", l: ["Lage: Alarm ist ausgelöst und an die Feuerwehr weitergeleitet; Ursache nur behauptet.", "Den Alarm nicht eigenmächtig zurückstellen oder abbestellen.", "Nach Alarmplan handeln: Feuerwehr erwarten und einweisen.", "Wenn im Alarmplan vorgesehen und gefahrlos möglich: Lage vor Ort erkunden und der Feuerwehr bzw. Leitstelle melden.", "Dem Koch freundlich erklären, dass die Entscheidung bei der Feuerwehr liegt.", "Räumung nach Brandschutzordnung, bis die Feuerwehr Entwarnung gibt.", "Rückstellen der Anlage nur durch Feuerwehr oder Berechtigte.", "Auslösung, Ursache und Maßnahmen dokumentieren."], k: ["Kein eigenmächtiges Rückstellen", "Alarmplan als Maßstab", "Kommunikation mit Feuerwehr", "Dokumentation"], f: ["Dem Wunsch nachgeben", "Sirene abschalten", "Ohne Meldung selbst nachsehen und die Zentrale unbesetzt lassen"], r: "Brandschutzordnung; Alarmplan; § 145 StGB (Missbrauch von Notrufen als Gegenstück)" },

  { title: "Räumung des Bürohauses", topic: "Evakuierung", s: "Wegen einer Bombendrohung ordnet die Polizei die Räumung des von Ihnen bewachten Bürogebäudes an. Mitarbeiter fragen Sie aufgeregt, was los ist.", a: "Welche Aufgaben haben Sie?", l: ["Lage: Gefahrenlage unter polizeilicher Leitung; Unruhe unter den Mitarbeitern.", "Eigensicherung: Anweisungen der Polizei befolgen, nichts Verdächtiges berühren.", "Ruhig und knapp informieren: „Bitte verlassen Sie das Gebäude über das Treppenhaus und gehen Sie zum Sammelplatz.“ Keine Spekulationen.", "Personen leiten, Aufzüge sperren, Hilfsbedürftige unterstützen.", "Ihre Objektkenntnis der Polizei zur Verfügung stellen: Pläne, Schlüssel, Besucherliste.", "Zugänge sichern, niemanden zurück ins Gebäude lassen.", "Verdächtige Beobachtungen sofort an die Polizei.", "Zeiten und Maßnahmen dokumentieren."], k: ["Leitung liegt bei der Polizei", "Ruhige, sachliche Information", "Besucherliste und Objektkenntnis", "Zutritt verhindern"], f: ["Gerüchte weitergeben", "Selbst nach dem Gegenstand suchen", "Mitarbeiter zurücklassen, um Sachen zu holen"], r: "§ 8 Abs. 1, § 34 PolG NRW; Alarmplan; § 126 StGB" },
  { title: "Rollstuhlfahrerin im vierten Stock", topic: "Evakuierung", s: "Bei einem Feueralarm treffen Sie im vierten Stock eine Besucherin im Rollstuhl. Die Aufzüge sind außer Betrieb. Im Treppenraum ist noch kein Rauch.", a: "Was tun Sie?", l: ["Lage: hilfsbedürftige Person, Fluchtweg nur über die Treppe.", "Eigensicherung: Rauchentwicklung beobachten, Rückzugsweg.", "Die Frau ansprechen, beruhigen, fragen, wie sie am besten unterstützt werden kann.", "Sofort über Funk melden: Ort, eine Person im Rollstuhl, Unterstützung nötig.", "Mit Helfern über die Treppe bringen, wenn es sicher möglich ist; sonst in einen sicheren Bereich – möglichst rauchfreier Treppenraum bzw. ausgewiesene Wartezone – und bei ihr bleiben oder Betreuung sicherstellen.", "Türen hinter sich schließen.", "Der Feuerwehr den genauen Standort melden.", "Am Sammelplatz Rückmeldung geben; dokumentieren."], k: ["Hilfsbedürftige nicht allein lassen", "Meldung des Standorts", "Sicherer Bereich als Alternative", "Kommunikation mit der Betroffenen"], f: ["Aufzug benutzen", "Die Frau zurücklassen und „Hilfe holen“ ohne Meldung", "Über ihren Kopf hinweg entscheiden"], r: "Brandschutzordnung; § 323c StGB; DGUV Vorschrift 1" },

  { title: "Übergabe an die Polizei", topic: "Polizei", s: "Sie haben einen Mann nach einem Handtaschenraub im Parkhaus festgehalten. Zwei Polizeibeamte treffen ein.", a: "Was teilen Sie der Polizei mit, und was geschieht mit Ihrer Rolle?", l: ["Lage: Übergabe eines Festgenommenen; Sie sind jetzt Zeuge.", "Eigensicherung: Person erst loslassen, wenn die Polizei sie übernommen hat.", "Knappe Lagemeldung: wer, was, wann, wo – was Sie selbst gesehen haben.", "Angeben, welche Zwangsmittel Sie angewendet haben und ob jemand verletzt ist.", "Opfer, Zeugen und Beweismittel benennen; auf Videoaufzeichnung hinweisen.", "Ab jetzt keine eigenen Maßnahmen mehr; Weisungen der Polizei folgen.", "Eigene Personalien als Zeuge angeben.", "Eigenen Bericht zeitnah schreiben; Vorgesetzte informieren."], k: ["Strukturierte Übergabe", "Eigene Wahrnehmung von Hörensagen getrennt", "Zwangsanwendung offen gelegt", "Rollenwechsel zum Zeugen"], f: ["Ausschmücken", "Zwang verschweigen", "Weiter „mit ermitteln“"], r: "§ 127 Abs. 1 StPO; § 163 StPO; §§ 48, 57 StPO" },
  { title: "Polizei will ins Objekt", topic: "Polizei", s: "Nachts klingeln zwei Personen in Zivil an der Pforte des Werks, sagen, sie seien von der Kriminalpolizei und müssten sofort ins Büro des Geschäftsführers.", a: "Wie verhalten Sie sich?", l: ["Lage: unbekannte Personen, behauptete Polizeieigenschaft, nachts.", "Eigensicherung: hinter der Pforte bleiben, Tür nicht öffnen, Leitstelle informieren.", "Höflich um Dienstausweise bitten und diese in Ruhe prüfen.", "Bei Zweifeln Rückruf bei der Polizeidienststelle über die offiziell bekannte Nummer bzw. 110.", "Nach Dienstanweisung den Ansprechpartner des Auftraggebers verständigen.", "Bestätigt sich die Polizei und liegt eine Maßnahme vor, Zutritt gewähren und begleiten; nicht behindern.", "Nicht bestätigt: Zutritt verweigern, Polizei rufen.", "Zeit, Namen, Dienststelle, Anlass dokumentieren."], k: ["Legitimation prüfen", "Rückruf über offizielle Nummer", "Dienstanweisung und Meldeweg", "Kooperation bei echter Maßnahme"], f: ["Ungeprüft einlassen", "Echten Beamten den Zutritt dauerhaft verweigern", "Niemanden informieren"], r: "Dienstanweisung; § 132 StGB (Amtsanmaßung als Risiko); § 903 BGB" },

  { title: "Herzinfarkt am Arbeitsplatz", topic: "Rettungsdienst", s: "Ein Mitarbeiter des Kunden ruft Sie an: Ein Kollege sei im Büro zusammengebrochen und atme nicht normal.", a: "Schildern Sie Ihre Maßnahmen.", l: ["Lage: lebensbedrohlicher Notfall; jede Minute zählt.", "Sofort Notruf 112: Adresse, Gebäudeteil, Etage, „Person atmet nicht normal“, Rückrufnummer.", "Anrufer anleiten: Herzdruckmassage beginnen; nächsten AED holen lassen.", "Selbst mit AED und Erste-Hilfe-Material zum Ort oder einen Kollegen schicken.", "Zufahrt öffnen, Aufzug bereitstellen, Einweiser an den Eingang.", "Rettungsdienst auf dem kürzesten Weg zum Patienten führen.", "Schaulustige fernhalten, Privatsphäre wahren.", "Auftraggeber informieren, Zeiten dokumentieren."], k: ["Vollständiger Notruf", "Wiederbelebung und AED", "Einweisung des Rettungsdienstes", "Parallel organisieren"], f: ["Erst hingehen, dann anrufen", "Pforte verlassen ohne Einweisung zu regeln", "Unklare Ortsangabe"], r: "§ 323c StGB; § 2 Abs. 1 DGUV Vorschrift 1 (wirksame Erste Hilfe)" },
  { title: "Verletzter lehnt Hilfe ab", topic: "Rettungsdienst", s: "Ein Besucher stürzt auf der Treppe, blutet am Kopf und wirkt kurz benommen. Er sagt: „Kein Arzt, ich muss zum Termin.“", a: "Was tun Sie?", l: ["Lage: Kopfverletzung mit Benommenheit – Gefahr einer ernsten Verletzung.", "Eigensicherung: Handschuhe.", "Ansprechen, hinsetzen lassen, Wunde versorgen.", "Eindringlich raten, sich untersuchen zu lassen; Risiken erklären.", "Eine einsichtsfähige erwachsene Person darf Hilfe ablehnen – nicht festhalten.", "Bei Bewusstseinsstörung oder Verschlechterung Rettungsdienst rufen – dann geht die Hilfspflicht vor.", "Begleitung oder Abholung anbieten.", "Unfall, Ablehnung, Zeugen dokumentieren; Unfallstelle prüfen und Mangel melden."], k: ["Hilfspflicht und Selbstbestimmung abgewogen", "Kriterium Einsichtsfähigkeit", "Dokumentation der Ablehnung", "Ursache des Sturzes prüfen"], f: ["Zwang anwenden", "Einfach gehen lassen ohne Erstversorgung und Notiz", "Unfallstelle nicht sichern"], r: "§ 323c StGB; § 239 StGB; § 823 BGB (Verkehrssicherung)" },

  { title: "Falschparker auf der Straße", topic: "Grenzen privater Sicherheitskräfte", s: "Der Auftraggeber bittet Sie, vor seinem Geschäft auf der öffentlichen Straße „für Ordnung zu sorgen“: Falschparker aufschreiben, Zettel verteilen und notfalls die Luft aus den Reifen lassen.", a: "Was davon dürfen Sie?", l: ["Lage: öffentlicher Verkehrsraum – kein Hausrecht des Auftraggebers.", "Dem Auftraggeber freundlich die Grenzen erklären.", "Verkehrsüberwachung und Verwarnungen sind hoheitliche Aufgaben von Ordnungsamt und Polizei.", "Zulässig: Fahrer höflich ansprechen und bitten wegzufahren; Behörde informieren.", "Unzulässig: „Knöllchen“ mit amtlichem Anschein – Amtsanmaßung.", "Luft ablassen wäre Sachbeschädigung bzw. Nötigung.", "Auf dem Privatparkplatz gilt dagegen das Hausrecht; dort sind Hinweisschilder und Abschleppen über den Besitzer möglich.", "Gespräch mit dem Auftraggeber dem Vorgesetzten melden."], k: ["Öffentlicher Raum vs. Hausrechtsbereich", "Hoheitliche Aufgabe erkannt", "Straftaten benannt", "Zulässige Alternative"], f: ["Dem Kunden alles zusagen", "Amtlich wirkende Zettel", "Selbstjustiz"], r: "§ 34a Abs. 5 GewO; § 132 StGB; § 303 StGB; § 240 StGB; DGUV Vorschrift 23 § 4 Abs. 3" },
  { title: "„Ausweis her!“", topic: "Grenzen privater Sicherheitskräfte", s: "Ein neuer Kollege verlangt von einem Jugendlichen, der im Einkaufszentrum auf dem Geländer sitzt, barsch den Ausweis und droht: „Sonst nehme ich dich mit auf die Wache.“", a: "Bewerten Sie das Verhalten und beschreiben Sie, wie es richtig wäre.", l: ["Lage: Bagatellverstoß gegen die Hausordnung; Kollege überschreitet seine Rechte.", "Situation übernehmen, bevor sie eskaliert – ruhig, ohne den Kollegen bloßzustellen.", "Richtig: höflich ansprechen, auf die Gefahr und die Hausordnung hinweisen, bitten herunterzukommen.", "Ein Ausweis darf erbeten, aber nicht erzwungen werden.", "„Wache“ und „mitnehmen“ suggerieren Polizeibefugnisse – das ist unzulässig und kann Amtsanmaßung bzw. Nötigung sein.", "Bei Weigerung: Hausverbot als mildes Mittel des Hausrechts.", "Polizei nur bei Straftaten oder Gefahr.", "Kollegen danach unter vier Augen korrigieren; Vorgesetzten informieren, wenn es sich wiederholt."], k: ["Befugnisüberschreitung erkannt", "Richtige Alternative", "Kollegiales, aber klares Eingreifen", "Verhältnismäßigkeit"], f: ["Kollegen decken", "Kollegen vor dem Jugendlichen vorführen", "Selbst mit Zwang drohen"], r: "§ 34a Abs. 5 GewO; § 17 BewachV; §§ 132, 240 StGB" },
  { title: "Spindkontrolle auf Kundenwunsch", topic: "Grenzen privater Sicherheitskräfte", s: "Der Lagerleiter des Kunden fordert Sie auf, nach Schichtende die verschlossenen Privatspinde der Mitarbeiter mit dem Generalschlüssel zu öffnen und nach Diebesgut zu durchsuchen.", a: "Dürfen Sie das?", l: ["Lage: Eingriff in die Privatsphäre von Beschäftigten ohne deren Wissen.", "Höflich ablehnen und begründen.", "Durchsuchungen sind hoheitliche Maßnahmen; ein privater Auftrag ersetzt weder Einwilligung noch gesetzliche Grundlage.", "Heimliches Öffnen verletzt Persönlichkeitsrecht und Datenschutz und kann zivil- und arbeitsrechtliche Folgen haben.", "Zulässige Wege aufzeigen: Kontrollen nur auf klarer betrieblicher Grundlage, im Beisein der Betroffenen und der Arbeitnehmervertretung; bei konkretem Verdacht Polizei.", "Tor- und Taschenkontrollen sind ebenfalls nur freiwillig bzw. auf vereinbarter Grundlage möglich.", "Eigenen Vorgesetzten informieren.", "Anfrage dokumentieren."], k: ["Grenze klar gezogen", "Rechtsgüter benannt", "Zulässige Alternativen", "Meldung an eigene Firma"], f: ["„Der Kunde zahlt, also mache ich es“", "Heimlich nachsehen", "Schroffe Ablehnung ohne Erklärung"], r: "§ 34a Abs. 5 GewO; Art. 2 Abs. 1, Art. 1 Abs. 1 GG; § 26 BDSG; DGUV Vorschrift 23 § 4 Abs. 3" },

  { title: "Missverständnis am Telefon", topic: "Kommunikation", s: "Ein Lieferant ruft an der Pforte an. Sie sagen: „Fahren Sie hinten rum.“ Zehn Minuten später steht der Lkw in einer Sackgasse auf dem Werksgelände und blockiert einen Rettungsweg. Der Fahrer ist wütend.", a: "Was ist kommunikativ schiefgelaufen, und wie lösen Sie die Situation?", l: ["Lage: Blockierter Rettungsweg – zuerst die Gefahr beseitigen.", "Fahrer ruhig ansprechen, nicht die Schuldfrage diskutieren.", "Eigenen Anteil benennen: „Meine Beschreibung war ungenau, das tut mir leid.“", "Klare Einweisung zum Zurücksetzen geben, Einweiser stellen.", "Ursache: unklare, mehrdeutige Aussage ohne Rückfrage; kein gemeinsames Bild.", "Besser: konkrete Wegbeschreibung mit Merkpunkten, Tornummer, Rückfrage „Haben Sie das Tor 3 gefunden?“", "Bei Bedarf Lageplan oder Lotsen nutzen.", "Vorfall notieren, Wegbeschreibung für die Pforte verbessern."], k: ["Gefahr zuerst", "Eigener Anteil, keine Rechtfertigung", "Ursache im Sender-Empfänger-Modell", "Konkrete Verbesserung"], f: ["Dem Fahrer die Schuld geben", "Lange Diskussion bei blockiertem Rettungsweg", "Nichts daraus lernen"], r: "Rahmenplan Sachgebiet 6 (Kommunikation); DGUV Vorschrift 23 § 8" },
  { title: "Beschwerde über einen Kollegen", topic: "Kommunikation", s: "Eine Besucherin beschwert sich bei Ihnen lautstark, Ihr Kollege habe sie am Eingang „wie eine Verbrecherin behandelt“.", a: "Wie führen Sie das Gespräch?", l: ["Lage: verärgerte Besucherin, Beziehungsebene verletzt; Sie kennen den Hergang nicht.", "Ruhigen Ort anbieten, hinsetzen, Zeit nehmen.", "Aktiv zuhören, ausreden lassen, zusammenfassen: „Wenn ich Sie richtig verstehe …“", "Verständnis für das Gefühl zeigen, ohne den Kollegen vorzuverurteilen.", "Sachverhalt mit offenen Fragen klären: Was genau ist passiert?", "Erklären, warum es Kontrollen gibt; zusichern, dass Sie die Beschwerde weitergeben.", "Nicht versprechen, was Sie nicht halten können.", "Beschwerde notieren, an Vorgesetzten weiterleiten, Kollegen später sachlich informieren."], k: ["Aktives Zuhören", "Neutralität", "Trennung von Gefühl und Sache", "Verbindlicher Abschluss"], f: ["Kollegen sofort verteidigen", "Kollegen vor der Kundin schlechtmachen", "Beschwerde nicht weitergeben"], r: "Rahmenplan Sachgebiet 6 (Gesprächsführung)" },

  { title: "Streit an der Kasse", topic: "Deeskalation", s: "Im Supermarkt beschimpft ein Kunde die Kassiererin, weil seine Karte nicht funktioniert. Die Schlange wird länger, andere Kunden mischen sich ein.", a: "Wie deeskalieren Sie?", l: ["Lage: Frustration und Scham vor Publikum; noch verbale Ebene.", "Eigensicherung: seitlich nähern, Abstand, Hände sichtbar.", "Freundlich ansprechen: „Guten Tag, kann ich helfen? Kommen Sie, wir klären das hier drüben.“", "Kunden vom Publikum wegführen – Gesichtswahrung.", "Zuhören, Problem benennen, Lösung anbieten: andere Zahlungsart, Geldautomat, Ware zurücklegen.", "Grenze freundlich benennen: Beleidigungen gehen nicht.", "Erst bei Fortsetzung Hausrecht: Bitte, das Geschäft zu verlassen; bei Bedrohung Polizei.", "Kassiererin kurz ansprechen und entlasten; Vorfall notieren."], k: ["Ursache erkannt", "Räumliche Trennung vom Publikum", "Lösungsangebot", "Abgestuftes Vorgehen"], f: ["Belehren", "Sofort Hausverbot", "Kassiererin ignorieren"], r: "Rahmenplan Sachgebiet 6; § 903 BGB; § 185 StGB" },
  { title: "Zwei Lager im Wartebereich", topic: "Deeskalation", s: "Im Wartebereich eines Amtes, das Sie bewachen, streiten zwei Familien lautstark um die Reihenfolge. Es wird geschubst. Kinder weinen.", a: "Wie gehen Sie vor?", l: ["Lage: zwei Gruppen, beginnende körperliche Auseinandersetzung, Kinder anwesend.", "Eigensicherung: Kollegen rufen, nicht zwischen die Gruppen stellen, bevor Unterstützung da ist.", "Laut, klar und ruhig: „Stopp. Bitte gehen Sie auseinander.“", "Gruppen räumlich trennen – je ein Kollege pro Gruppe.", "Je einen Sprecher ansprechen, zuhören, Reihenfolge sachlich klären lassen.", "Neutral bleiben, niemanden bevorzugen.", "Bei Schlägen: Nothilfe, Polizei rufen; Hausrecht des Amtes über die Leitung.", "Dokumentation, Meldung an die Behördenleitung."], k: ["Trennen vor Reden", "Sprecherprinzip", "Neutralität", "Schutz der Kinder"], f: ["Allein dazwischen gehen", "Partei ergreifen", "Schreien"], r: "Rahmenplan Sachgebiet 6; § 32 StGB; Hausrecht der Behörde" },
  { title: "Provokation vor Zuschauern", topic: "Deeskalation", s: "Ein Jugendlicher filmt Sie mit dem Handy, hält Ihnen die Kamera vors Gesicht und sagt: „Na, Möchtegern-Polizist, was willst du machen?“ Seine Freunde lachen.", a: "Wie reagieren Sie professionell?", l: ["Lage: gezielte Provokation für Publikum und Video; Ziel ist Ihre Überreaktion.", "Eigensicherung: Schritt zurück, Abstand herstellen.", "Nicht persönlich nehmen – die Provokation gilt der Rolle.", "Ruhig und knapp: „Bitte halten Sie Abstand. Wenn Sie etwas brauchen, helfe ich gern.“", "Handy nicht wegschlagen oder wegnehmen – das wäre Nötigung bzw. Sachbeschädigung.", "Auf Hausordnung hinweisen, wenn Filmen untersagt ist; bei Fortsetzung Hausverbot.", "Veröffentlichung ohne Einwilligung kann Ihr Recht am eigenen Bild verletzen – rechtliche Schritte später, nicht vor Ort erzwingen.", "Vorfall notieren, ggf. Vorgesetzten informieren."], k: ["Selbstkontrolle", "Abstand statt Konfrontation", "Keine Selbstjustiz am Handy", "Rechtliche Einordnung des Filmens"], f: ["Handy wegnehmen", "Zurückbeleidigen", "Sich auf eine Diskussion vor Publikum einlassen"], r: "Rahmenplan Sachgebiet 6; § 22 KunstUrhG; § 240 StGB; § 903 BGB" },

  { title: "Schuhe im Gebetsraum", topic: "Interkulturelle Konflikte", s: "In einer Unterkunft für Geflüchtete sollen Sie nachts einen Kontrollgang machen. Bewohner bitten Sie verärgert, den als Gebetsraum genutzten Raum nicht mit Schuhen zu betreten. Ihr Auftrag verlangt die Kontrolle aller Räume auf Brandgefahren.", a: "Wie lösen Sie den Konflikt?", l: ["Lage: Sicherheitsauftrag trifft auf religiöse Regel; Vertrauen steht auf dem Spiel.", "Ruhig bleiben, Wertschätzung zeigen: „Ich möchte Ihren Raum respektieren.“", "Auftrag erklären: kurze Sichtkontrolle wegen Brandschutz, zum Schutz aller.", "Lösung suchen, die beides wahrt: Überschuhe, Blick von der Tür, Kontrolle in Begleitung eines Bewohners, Zeitpunkt außerhalb des Gebets.", "Bei akuter Gefahr geht die Sicherheit vor – das offen sagen.", "Sprachmittler nutzen, wenn nötig.", "Regelung mit der Einrichtungsleitung abstimmen und für alle Schichten festhalten.", "Vorgang sachlich dokumentieren."], k: ["Respekt und Auftrag in Einklang", "Kreative, verhältnismäßige Lösung", "Vorrang der Gefahrenabwehr", "Dauerhafte Regelung"], f: ["Stur durchgehen", "Kontrolle ganz unterlassen", "Abfällige Bemerkungen"], r: "Rahmenplan Sachgebiet 6 (interkulturelle Kompetenz); Art. 4 GG; Brandschutzordnung" },
  { title: "Kein Handschlag", topic: "Interkulturelle Konflikte", s: "Eine Kollegin beschwert sich bei Ihnen als Schichtleiter: Ein Besucher habe ihr den Handschlag verweigert und nur mit dem männlichen Kollegen gesprochen. Sie fühlt sich missachtet und will ihn künftig nicht mehr abfertigen.", a: "Wie gehen Sie als Schichtleiter damit um?", l: ["Lage: Kränkung der Kollegin; mögliches kulturelles oder religiöses Verhalten des Besuchers; Dienstbetrieb muss funktionieren.", "Kollegin ernst nehmen, zuhören, Gefühl anerkennen.", "Einordnen: Ein verweigerter Handschlag kann religiöse oder persönliche Gründe haben und muss keine Abwertung sein.", "Klarstellen: Wer im Objekt etwas will, wird von der zuständigen Wachperson abgefertigt – gleich welchen Geschlechts.", "Dem Besucher gegenüber freundlich und bestimmt auftreten; keine Sonderbehandlung, aber auch kein erzwungener Handschlag.", "Kollegin stärken statt sie abzuziehen.", "Bei respektlosem oder beleidigendem Verhalten Hausrecht anwenden.", "Thema in der Teamunterweisung aufgreifen."], k: ["Fürsorge für die Mitarbeiterin", "Differenzierte Deutung", "Gleichbehandlung im Dienst", "Führungsverhalten"], f: ["Kollegin abtun", "Besucher pauschal verurteilen", "Dem Besucher nachgeben und nur Männer einsetzen"], r: "Rahmenplan Sachgebiet 6; Art. 3 GG; AGG" },

  { title: "„Die kommen hier nicht rein“", topic: "Diskriminierung und Diversität", s: "Der Betreiber eines Clubs sagt Ihnen vor Dienstbeginn: „Heute lasst ihr keine Gruppen von Südländern rein, die machen nur Ärger.“", a: "Wie reagieren Sie?", l: ["Lage: rechtswidrige, diskriminierende Weisung.", "Ruhig und sachlich widersprechen.", "Rechtslage: Einlass darf nicht wegen ethnischer Herkunft verweigert werden – Verstoß gegen das AGG, mit Entschädigungsansprüchen und Rufschaden.", "Zulässige Kriterien anbieten: Alkoholisierung, aggressives Verhalten, Kleiderordnung, Hausverbote, Kapazität – für alle gleich.", "Klarstellen, dass Sie die Weisung so nicht ausführen.", "Eigenen Vorgesetzten informieren.", "An der Tür jede Abweisung mit sachlichem Grund erklären.", "Gespräch notieren."], k: ["Diskriminierung erkannt", "AGG und Art. 3 GG", "Sachliche Alternativen", "Haltung trotz Druck"], f: ["Weisung befolgen", "Vorgeschobene Gründe erfinden", "Konflikt mit dem Kunden scheuen und schweigen"], r: "§§ 1, 19, 21 AGG; Art. 3 GG; DGUV Vorschrift 23 § 4 Abs. 3" },
  { title: "Beleidigung wegen der Herkunft", topic: "Diskriminierung und Diversität", s: "Ein Kunde beschimpft Ihre Kollegin an der Information mit rassistischen Ausdrücken, weil sie ihm keine Auskunft geben kann.", a: "Was tun Sie?", l: ["Lage: Straftat (Beleidigung) gegen eine Kollegin; Würde und Schutz der Mitarbeiterin.", "Eigensicherung: dazutreten, Abstand zum Kunden.", "Klar und ruhig: „So sprechen Sie hier mit niemandem. Hören Sie bitte auf.“", "Kollegin aus der Situation nehmen bzw. sich vor sie stellen.", "Hausrecht: Hausverbot aussprechen und zum Verlassen auffordern.", "Personalien erbitten; Zeugen sichern.", "Auf Wunsch der Kollegin Polizei rufen – Beleidigung ist Antragsdelikt, Frist drei Monate.", "Vorfall mit Wortlaut dokumentieren; Kollegin Unterstützung anbieten."], k: ["Schutz der Kollegin", "Klare Grenze", "Antragsdelikt und Frist", "Nachsorge"], f: ["Verharmlosen („der meint das nicht so“)", "Selbst ausfallend werden", "Wortlaut nicht festhalten"], r: "§ 185 StGB; § 194 StGB; § 77b StGB; § 903 BGB; AGG" }
]);
